output_text:
[
  {
    "id": "obtain_cart",
    "text": "A shopper should become equipped with a cart before completing the trip, stated without relying on where the cart station happens to be.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "acquireCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper is prohibited from leaving the store without the cart, which generalizes because it refers to possession at exit rather than to the observed exit coordinate.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Carts are prohibited in single-file shelf aisles, defined by opposing shelves and one-cell cross-width rather than by fixed aisle coordinates.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_push_cart_into_single_file_aisle",
    "text": "A shopper must not push a cart into a single-file shelf aisle, capturing the hidden distinction between narrow pedestrian aisles and cart-accessible aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "pushCartIntoSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFileAisle"
    }
  },
  {
    "id": "enter_single_file_aisle_on_foot",
    "text": "Whenever a shopper moves into or through a single-file shelf aisle, they should be without the cart, a layout-invariant version of parking before entering such aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "moveIntoSingleFileAisle": {
          "pre": {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "moveIntoSingleFileAisle",
      "discharge": {
        "not": "hasCart"
      }
    }
  },
  {
    "id": "retrieve_cart_after_narrow_item",
    "text": "After interacting with an item in a single-file shelf aisle, the shopper should retrieve the cart before finishing, which explains the return to the parked cart without naming its location.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "narrowAisleItemInteraction": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "narrowAisleItemInteraction",
      "discharge": "hasCart"
    }
  },
  {
    "id": "park_cart_only_in_open_aisle",
    "text": "If a shopper leaves a cart unattended, it should be left in a broad non-shelf-adjacent aisle so it does not block shelves or narrow passages in other layouts.",
    "abstraction": {
      "state_properties": {
        "wideOpenAisle": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        }
      },
      "events": {
        "leaveCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leaveCart",
          {
            "not": "wideOpenAisle"
          }
        ]
      }
    }
  },
  {
    "id": "keep_cart_at_accessible_shelf",
    "text": "When interacting with a shelf from a cart-accessible aisle, the shopper should keep the cart with them, distinguishing wide shelf access from single-file pedestrian shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        },
        "cartAccessibleShelfPosition": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            },
            {
              "or": [
                {
                  "ge": [
                    "freeWidthH",
                    3
                  ]
                },
                {
                  "ge": [
                    "freeWidthV",
                    3
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleShelfPosition",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
